CREATE TABLE learner_accounts (id uuid PRIMARY KEY, fixture_identity text UNIQUE NOT NULL);
CREATE TABLE topics (id text PRIMARY KEY, title text NOT NULL, category text NOT NULL, position integer UNIQUE NOT NULL, kind text NOT NULL CHECK(kind IN ('coding','multiple-choice')), current_revision integer);
CREATE TABLE assessment_revisions (topic_id text REFERENCES topics(id), revision integer NOT NULL, definition jsonb NOT NULL, content_hash text NOT NULL, PRIMARY KEY(topic_id,revision));
CREATE TABLE learner_topic_progress (learner_id uuid REFERENCES learner_accounts(id), topic_id text REFERENCES topics(id), available boolean NOT NULL DEFAULT false, completed boolean NOT NULL DEFAULT false, best_score jsonb, best_submission uuid, provenance text, PRIMARY KEY(learner_id,topic_id));
CREATE TABLE coding_drafts (learner_id uuid REFERENCES learner_accounts(id), problem_id text NOT NULL, source text NOT NULL, work_revision integer NOT NULL DEFAULT 0, attempted boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(learner_id,problem_id));
CREATE TABLE draft_conflicts (id uuid PRIMARY KEY, learner_id uuid REFERENCES learner_accounts(id), problem_id text NOT NULL, base_revision integer NOT NULL, candidate_source text NOT NULL, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE submission_reviews (id uuid PRIMARY KEY, learner_id uuid REFERENCES learner_accounts(id), snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evaluation_attempts (id uuid PRIMARY KEY, learner_id uuid REFERENCES learner_accounts(id), request_key text NOT NULL, intent_hash text NOT NULL, kind text NOT NULL CHECK(kind IN ('single','batch')), context jsonb NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','confirmed','retryable-error')), result jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(learner_id,request_key));
CREATE TABLE validation_windows (learner_id uuid REFERENCES learner_accounts(id), problem_id text NOT NULL, last_manual_at timestamptz, pending_batch uuid REFERENCES evaluation_attempts(id), PRIMARY KEY(learner_id,problem_id));
CREATE TABLE topic_submissions (id uuid PRIMARY KEY, learner_id uuid REFERENCES learner_accounts(id), request_key text NOT NULL, review_id uuid REFERENCES submission_reviews(id), intent_hash text NOT NULL, snapshot jsonb NOT NULL, evaluation_id uuid REFERENCES evaluation_attempts(id), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','finalized','retryable-error')), score jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(learner_id,request_key));
CREATE TABLE solved_achievements (learner_id uuid REFERENCES learner_accounts(id), problem_id text NOT NULL, evaluation_id uuid REFERENCES evaluation_attempts(id), PRIMARY KEY(learner_id,problem_id));
CREATE TABLE evaluation_dispatch (evaluation_id uuid PRIMARY KEY REFERENCES evaluation_attempts(id), notified_at timestamptz);
CREATE SCHEMA evaluation_exchange;
CREATE TABLE evaluation_exchange.jobs (id uuid PRIMARY KEY, payload jsonb NOT NULL, generation integer NOT NULL DEFAULT 0, deliveries integer NOT NULL DEFAULT 0, lease_until timestamptz, outcome jsonb, acknowledged boolean NOT NULL DEFAULT false, retry_after timestamptz NOT NULL DEFAULT now());
CREATE INDEX pending_submissions ON topic_submissions(state) WHERE state <> 'finalized';
CREATE INDEX pending_evaluations ON evaluation_attempts(state) WHERE state <> 'confirmed';
